using Medzo.CatalogueInventory.Application.Common;using Microsoft.AspNetCore.Diagnostics;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace Medzo.CatalogueInventory.Api.ExceptionHandling;
public sealed class ApiExceptionHandler(IProblemDetailsService problems,ILogger<ApiExceptionHandler> log):IExceptionHandler{public async ValueTask<bool> TryHandleAsync(HttpContext c,Exception e,CancellationToken ct){var(status,title,errors)=e switch{NotFoundException=>(404,"Resource not found",null),ConflictException=>(409,"Conflict",null),ValidationException v=>(400,"Validation failed",v.Errors),DbUpdateConcurrencyException=>(409,"The resource changed; reload and retry.",null),_=>(500,"An unexpected error occurred.",null)};if(status==500)log.LogError(e,"Unhandled request error");c.Response.StatusCode=status;return await problems.TryWriteAsync(new(){HttpContext=c,ProblemDetails=new ProblemDetails{Status=status,Title=title,Detail=status==500?null:e.Message,Extensions={{"errors",errors}}},Exception=e});}}
